const ombre = (a: number) => `rgba(8,4,2,${a})`;
const sisal = (a: number) => `rgba(${SISAL},${a})`;
/** Les facettes du biseau, de la plus claire à la plus sombre. */
const FACETTES = [0.5, 0.24, -0.16, -0.55];
const teinte = (v: number, k: number) => (v > 0 ? sisal(v * k) : ombre(-v * k));

type Sillon = { sombre: string; clair: string; fond: string };

/** Un biseau de largeur constante : ses facettes, tracées d'un trait de 2w coupé à la forme. */
function Biseau({ d, clip, w, k = 1 }: { d: readonly string[]; clip: string; w: number; k?: number }) {
  return (
    <g clipPath={clip} fill="none" strokeLinejoin="round">
      {d.map((x, i) => (x ? <path key={i} d={x} stroke={teinte(FACETTES[i], k)} strokeWidth={2 * w} /> : null))}
    </g>
  );
}

/** Des sillons taillés en V (ou des arêtes) : la paroi d'ombre, la paroi de lumière, et le fond. */
function Taille({ s, sombre, clair, fond = 0, l = 1 }: { s: Sillon; sombre: number; clair: number; fond?: number; l?: number }) {
  return (
    <g>
      {fond > 0 ? <path d={s.fond} fill="none" stroke={ombre(fond)} strokeWidth={l} strokeLinecap="round" /> : null}
      <path d={s.sombre} fill={ombre(sombre)} />
      <path d={s.clair} fill={sisal(clair)} />
    </g>
  );
}

/** La moulure sous ses pieds : sculptée comme la chaîne du chambranle (l'ombre, le brin, son arête de lumière). */
function Moulure() {
  const w = 3.8;
  const brin = (d: string, cle: string) => (
    <g key={cle}>
      <path d={d} stroke="rgba(0,0,0,0.62)" strokeWidth={w + 2.4} transform="translate(1.6 2.4)" />
      <path d={d} stroke={`rgba(${BRUN},0.92)`} strokeWidth={w} />
      <path d={d} stroke={sisal(0.55)} strokeWidth={w * 0.34} transform="translate(-0.7 -0.9)" />
    </g>
  );
  return (
    <g fill="none" strokeLinecap="round" strokeLinejoin="round">
      <path d={MOULURE.filets} stroke="rgba(0,0,0,0.55)" strokeWidth={3.4} transform="translate(1 2)" />
      <path d={MOULURE.filets} stroke={`rgba(${BRUN},0.9)`} strokeWidth={2.6} />
      <path d={MOULURE.filets} stroke={sisal(0.42)} strokeWidth={1} transform="translate(-0.5 -0.8)" />
      {brin(MOULURE.brins, "b")}
      <path d={MOULURE.dessus} stroke="rgba(0,0,0,0.7)" strokeWidth={w * 1.8} strokeLinecap="butt" />
      {brin(MOULURE.dessus, "d")}
      <path d={MOULURE.perles} fill="rgba(0,0,0,0.5)" stroke="none" transform="translate(1 1.5)" />
      <path d={MOULURE.perles} fill={sisal(0.6)} stroke="none" />
    </g>
  );
}

/** Le relief du dos : le rhinocéros taillé dans la porte. */
function Relief({ id }: { id: string }) {
  const k = (n: string) => `${n}-${id}`;
  const u = (n: string) => `url(#${n}-${id})`;
  return (
    <g>
      <defs>
        <clipPath id={k("kc")}>
          <path d={CORPS} />
        </clipPath>
        <clipPath id={k("kl")}>
          <path d={LOIN} />
        </clipPath>
        <clipPath id={k("kq")}>
          <path d={QUEUE} />
        </clipPath>
        <clipPath id={k("ko")}>
          <path d={OREILLE + OREILLE_LOIN} />
        </clipPath>
        <clipPath id={k("kn")}>
          <path d={CORNE_AV + CORNE_AR} />
        </clipPath>
      </defs>

      <Moulure />

      {/* L'ombre que le relief porte sur le panneau, en bas à droite */}
      <path d={CORPS + LOIN + QUEUE + CORNE_AV + CORNE_AR + OREILLE + OREILLE_LOIN} fill={ombre(0.24)} transform="translate(9 13.5)" />
      <path d={CORPS + LOIN + QUEUE + CORNE_AV + CORNE_AR + OREILLE + OREILLE_LOIN} fill={ombre(0.5)} transform="translate(4.6 6.9)" />

      {/* Le relief bas : les pattes lointaines et l'oreille de derrière */}
      <path d={LOIN} fill={BOIS.loin} />
      <g clipPath={u("kl")}>
        <path d={P_LOIN_CLAIR} fill={BOIS.loinClair} />
        <path d={P_LOIN_OMBRE} fill={BOIS.loinOmbre} />
      </g>
      <Biseau d={BISEAU_LOIN} clip={u("kl")} w={5} k={0.6} />
      <path d={OREILLE_LOIN} fill={BOIS.loin} />

      {/* La queue, sur la fesse */}
      <path d={QUEUE} fill={BOIS.flanc} />
      <Biseau d={BISEAU_QUEUE} clip={u("kq")} w={3.5} />
      <Taille s={CRINS} sombre={0.55} clair={0.3} />

      {/* Le relief haut : les trois plans, la joue, les gouges, les sillons, les arêtes, le biseau */}
      <path d={CORPS} fill={BOIS.flanc} />
      <g clipPath={u("kc")}>
        <path d={P_LUMIERE} fill={BOIS.lumiere} />
        <path d={P_FACETTES} fill={BOIS.facette} />
        <path d={P_OMBRE} fill={BOIS.ombre} />
        <path d={P_PATTES_CLAIR} fill={BOIS.lumiere} />
        <path d={P_PATTES_OMBRE} fill={BOIS.ombre} />
        <path d={T_JOUE} fill={BOIS.joue} />
        <path d={T_GANACHE} fill={BOIS.ombre} />
        <Taille s={PEAU} sombre={0.34} clair={0.14} />
        <Taille s={CHANFREINS} sombre={0.16} clair={0.26} />
        <Taille s={PLIS} sombre={0.66} clair={0.42} fond={0.5} />
        <Taille s={PLIS_PATTES} sombre={0.52} clair={0.3} fond={0.35} />
        <Taille s={ARETES} sombre={0.5} clair={0.5} />
        <path d={ORBITE} fill={ombre(0.5)} />
        <Taille s={VISAGE} sombre={0.7} clair={0.4} fond={0.6} l={0.8} />
        <Biseau d={BISEAU_CORPS} clip={u("kc")} w={6.5} />
      </g>

      {/* L'œil, enfoncé ; le naseau ; les ongles */}
      <path d={AMANDE} fill="#120a05" />
      <path d={NASEAU} fill="#160c06" />
      <path d={ONGLES} fill={BOIS.ongle} />
      <Taille s={ENTAILLES_ONGLES} sombre={0.62} clair={0.34} />

      {/* L'oreille proche, levée : son creux, sa frange, son biseau */}
      <path d={OREILLE} fill={BOIS.flanc} />
      <path d={CORNET} fill={ombre(0.62)} />
      <Biseau d={BISEAU_OREILLES} clip={u("ko")} w={3.5} />
      <Taille s={FRANGE} sombre={0.6} clair={0.35} />

      {/* Les cornes, polies : la lumière sur le bord gauche, les fibres */}
      <path d={CORNE_AV + CORNE_AR} fill={BOIS.corne} />
      <g clipPath={u("kn")}>
        <Taille s={FIBRES} sombre={0.32} clair={0.26} />
      </g>
      <Biseau d={BISEAU_CORNES} clip={u("kn")} w={4} k={1.1} />
    </g>
  );
}

/**
 * La face : le rhinocéros entier, petit, gaufré dans le coin bas gauche du
 * portrait, à droite de l'équerre. Sans couleur et sans rien remplir : l'arête
 * de lumière (les facettes claires du biseau), le bord d'ombre, l'ombre portée
 * hors du corps seulement, l'œil.
 */
function Gaufrage({ id, photo }: { id: string; photo: boolean }) {
  const lumiere = (a: number) => `rgba(${CORAIL},${a})`;
  const k = photo ? 1 : 0.85;
  const tout = CORPS + LOIN + QUEUE + CORNE_AV + CORNE_AR + OREILLE + OREILLE_LOIN;
  const bord = (d: readonly string[], clip: string, w: number, a: number) => (
    <g clipPath={clip} fill="none" strokeLinejoin="round">
      {d[0] ? <path d={d[0]} stroke={lumiere(0.9 * a * k)} strokeWidth={2 * w} /> : null}
      {d[1] ? <path d={d[1]} stroke={lumiere(0.5 * a * k)} strokeWidth={2 * w} /> : null}
      {d[3] ? <path d={d[3]} stroke={ombre(0.6 * a * k)} strokeWidth={2 * w} /> : null}
    </g>
  );
  return (
    <g>
      <defs>
        <mask id={`kgm-${id}`} maskUnits="userSpaceOnUse" x={-60} y={-60} width={1120} height={760}>
          <rect x={-60} y={-60} width={1120} height={760} fill="#fff" />
          <path d={tout} fill="#000" />
        </mask>
        <clipPath id={`kgc-${id}`}>
          <path d={CORPS} />
        </clipPath>
        <clipPath id={`kgl-${id}`}>
          <path d={LOIN} />
        </clipPath>
        <clipPath id={`kgo-${id}`}>
          <path d={OREILLE + OREILLE_LOIN} />
        </clipPath>
        <clipPath id={`kgn-${id}`}>
          <path d={CORNE_AV + CORNE_AR} />
        </clipPath>
      </defs>
      <g mask={`url(#kgm-${id})`}>
        <path d={tout} fill={ombre(0.55 * k)} transform="translate(7 10)" />
      </g>
      {bord(BISEAU_LOIN, `url(#kgl-${id})`, 11, 0.6)}
      {bord(BISEAU_CORPS, `url(#kgc-${id})`, 13, 1)}
      {bord(BISEAU_OREILLES, `url(#kgo-${id})`, 10, 1.1)}
      {bord(BISEAU_CORNES, `url(#kgn-${id})`, 12, 1.1)}
      <circle cx={OEIL.x} cy={OEIL.y} r={8} fill={ombre(0.65 * k)} />
    </g>
  );
}

function Dessin({ couche, photo, id }: PropsTotem) {
  if (couche === "dos") return <Relief id={id} />;
  if (couche === "face-portrait") return <Gaufrage id={id} photo={photo} />;
  return null;
}

